<template><section class="page py-16"><form class="card mx-auto max-w-md p-7" @submit.prevent="submit"><h1 class="text-3xl font-bold">Create Account</h1><div class="mt-6 grid gap-4"><div><label class="label">Username</label><input v-model="form.username" class="input" required /></div><div><label class="label">Email</label><input v-model="form.email" type="email" class="input" required /></div><div><label class="label">Password</label><input v-model="form.password" type="password" minlength="8" class="input" required /></div></div><Message v-if="error" severity="error" class="mt-4">{{error}}</Message><Button type="submit" label="Register" :loading="loading" class="mt-6 w-full" /></form></section></template>
<script setup>
import { reactive,ref } from 'vue'; import { useRouter } from 'vue-router'; import Button from 'primevue/button'; import Message from 'primevue/message'; import { useAuthStore } from '../../stores/auth.js';
const form=reactive({username:'',email:'',password:''}),error=ref(''),loading=ref(false),auth=useAuthStore(),router=useRouter(); async function submit(){loading.value=true;try{await auth.register(form);router.push('/');}catch(e){error.value=e.response?.data?.message||e.message;}finally{loading.value=false;}}
</script>
